        self.photos_box = Gtk.VBox(homogeneous=False, spacing=6)
        self.refresh_gallery(None)


    def _refresh_entity(self, new_entity_id):
        old_entity = getattr(self, '_current_' + self.entity_class_name, None)
        current_entity = self._get_current_entity(new_entity_id)
        setattr(self, "_current_" + self.entity_class_name, current_entity)
        self._clear_photos()
        self._load_photos(current_entity)


    def _load_photos(self, entity_object):
        photos_paths = [photo.path for photo in entity_object.media]
        for path in photos_paths:
            img = Gtk.Image.new_from_file(path)
            self.photos_box.add(img)


    def _clear_photos(self):
        while len(self.photos_box.children()) != 0:
